from rules import resolve


def solve(data):
    return resolve(data)

def _has_cycle(graph):
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            return True
        if node in visited:
            return False
        visiting.add(node)
        for neighbor in graph.get(node, ()):
            if visit(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    return any(visit(node) for node in graph)


def resolve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    package_names = sorted(packages)

    def add_range(ranges, name, low, high):
        if name in ranges:
            old_low, old_high = ranges[name]
            low = max(low, old_low)
            high = min(high, old_high)
        if low > high:
            return False
        ranges[name] = (low, high)
        return True

    ranges = {}
    for name, interval in roots.items():
        if not add_range(ranges, name, interval[0], interval[1]):
            return {'error': 'unsatisfiable'}

    best_vector = None
    best_assignment = None

    def search(assignment, requirements, graph):
        nonlocal best_vector, best_assignment
        pending = sorted(name for name in requirements if name not in assignment)
        if not pending:
            vector = tuple(assignment.get(name, -1) for name in package_names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_assignment = assignment
            return

        name = pending[0]
        if name not in packages:
            return
        low, high = requirements[name]
        forbidden = set(blocked.get(name, []))
        rows = sorted(packages[name], key=lambda row: row['version'], reverse=True)

        for row in rows:
            version = row['version']
            if version < low or version > high or version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue

            next_assignment = dict(assignment)
            next_assignment[name] = version
            next_requirements = dict(requirements)
            next_graph = {node: set(edges) for node, edges in graph.items()}
            next_graph.setdefault(name, set())
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                next_graph.setdefault(target, set())
                next_graph[name].add(target)
                if not add_range(next_requirements, target, dep['min'], dep['max']):
                    valid = False
                    break
                if target in next_assignment:
                    target_version = next_assignment[target]
                    target_low, target_high = next_requirements[target]
                    if not target_low <= target_version <= target_high:
                        valid = False
                        break

            if valid and not _has_cycle(next_graph):
                search(next_assignment, next_requirements, next_graph)

    search({}, ranges, {})
    if best_assignment is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_assignment}
